"""无穷小、无穷大与无界：完整转录及62张采样板书逐项核对后的课堂。"""
def plan(example,check):
 return dict(minutes=45,bvid='BV1mCn36NEoN',
  summary='先固定趋近过程；无穷小趋零，绝对值无穷大要求最终全部超过任意阈值，无界只要求总能找到超出的值。',
  condition='先固定趋近方向与研究范围。无界要找任意大的值；否定绝对值无穷大要找持续回到有界范围的趋近点。倒数定理要求最终非零，不是仅仅不恒为零。',
  board='α→0：∀ε>0，最终 |α|<ε\n|f|→∞：∀M>0，最终全部 |f|>M\n无界：∀M>0，总能找到 |f|>M；反向推不出 |f|→∞\nα→0 且 |g|≤C ⇒ |αg|≤C|α|→0',
  text=[
   ('从差商理解“趋零”不等于“当成零”','研究 s(t)=t² 的瞬时变化率，先在 h≠0 时化简 [(t+h)²-t²]/h=2t+h，再令 h→0，得到极限 2t。约分的依据是 h≠0，最后取的是整个差商的极限；不是先令分母为零，又把同一个零约掉。数学史只作引入，课堂把重点放在这两个逻辑步骤。'),
   ('无穷小必须说清趋近过程','无穷小指在指定过程中极限为 0 的量。x→0 时，3x⁴、tan x、arcsin x、cos x-1 都是无穷小；cos x→1，所以它不是。x→+∞ 时，1/x 是无穷小，而 x 本身不是。固定非零常数再小，也无法满足任意精度要求；常零函数的极限为零，是唯一的常数无穷小。'),
   ('无穷大控制绝对值与全部邻近值','本课将“无穷大”明确用于 |f|→∞。例如 x→a 时：对每个 M>0，都存在 δ>0，使所有 0<|x-a|<δ 的输入满足 |f(x)|>M。正无穷与负无穷还要进一步限定符号；(-1)ⁿn 的绝对值趋于无穷，却既不趋 +∞ 也不趋 -∞。不要求单调：n+2(-1)ⁿ 虽然会回退，但不小于 n-2，所以仍趋 +∞。无穷大量没有有限实数极限；记号 ∞ 不当作普通实数参与四则运算。'),
   ('与无界比较时不偷换研究范围','在给定集合 I 上无界，是对每个 M>0，都能在 I 中找到一个 x 使 |f(x)|>M。要讨论 x→a 附近无界，还应能在任意小的去心邻域找到这样的值。无穷大要求足够近以后所有值都超过阈值，所以能推出附近无界；无界只提供存在性，不能保证其余值。函数在别处无界也不决定当前趋近点的行为。'),
   ('两组点列分担两个证明任务','源课主例题为 f(x)=sin(1/x)/x²，x→0⁺。取 x_n=1/(2πn+π/2)，有 f(x_n)=(2πn+π/2)²→+∞，故任何右侧小邻域都无界。另取 z_n=1/(nπ)，则 f(z_n)=0，且 z_n→0⁺；再靠近也有值回到零，故不满足 |f|→∞。这两步不能只写一半。原解析曾漏掉平方，课堂按题面及老师修正统一为 x²。'),
   ('运算定理把条件写在公式旁','同一过程中，非零无穷小的倒数是绝对值无穷大；“非零”要求在研究的足够小范围内不取零，不能仅说“不恒为零”。反之 |f|→∞ 时，f 最终非零且 1/f→0。有界量乘无穷小仍趋零：|g|≤C 时 |αg|≤C|α|→0。无穷大量加有界量仍是绝对值无穷大，因为 |f+g|≥|f|-C；与绝对值有正下界的量相乘也保持这一性质。仅仅 g≠0 不足以保证乘积无穷大。'),
   ('固定有限项与项数变化要分开','固定有限个无穷小之和、积仍是无穷小，但不能把结论套到项数随过程增加的和：n 个 1/n 相加恒为 1。两个无穷大量相减可能抵消，例如 (x+1)-x=1；无穷小与无穷大量的乘积也不能只凭类别判断。x→0⁺ 时，x·(1/x)=1，x²·(1/x)=x→0，x·(1/x²)=1/x→+∞。'),
   ('把有限极限写成常数加误差','f→A 等价于 f=A+α，其中 α=f-A→0。这是带误差的等式，不是把 α 当作零删去。若 x→0 时 f(x)/x²→6，则对去心邻域可写 f(x)/x²=6+α(x)，所以 f(x)=6x²+x²α(x)。不同无穷小的商可以趋常数、趋零、无穷大或振荡，需具体化简，不把 0/0 当数值答案。'),
   ('迁移练习所指的数列与适用边界','本课原有迁移题的“上述数列”仍指 a_n=n（n为奇数）、a_n=0（n为偶数）。奇数项可任意大，所以无界；任意门槛后仍有偶数项为零，所以不是绝对值无穷大。这个定义与源片 0,1,0,2,… 的例子不同，但两组子列的证明结构相同。先固定对象、趋近方向和范围，再选择定理。'),
  ],
  ex=example('判断 f(x)=sin(1/x)/x² 在 x→0⁺ 时是无穷小、无穷大，还是无界但非无穷大。','任意右侧去心邻域内无界，但不满足 |f(x)|→∞，也不是无穷小。',[
   ('找到任意高的取值','取 x_n=1/(2πn+π/2)→0⁺。sin(1/x_n)=1，故 f(x_n)=(2πn+π/2)²→+∞。'),
   ('找到任意近的零点','取 z_n=1/(nπ)→0⁺，sin(1/z_n)=sin(nπ)=0，所以 f(z_n)=0。'),
   ('分别使用量词得结论','第一组说明每个右侧小邻域内都能超过任意 M；第二组说明无论范围多小，总有值不能超过 M=1。因此无界但非无穷大，且第一组也排除了趋零。')]),
  stages=[
   ('对象、方向与量词','先回答一个问题：一个固定的小数，凭什么被叫作无穷小？小到让你看不清，不是定义。把趋近过程写出来，再看函数值能否满足任意精度。至于无穷大，注意我要检查的是绝对值，还要检查范围里的全部值。白厄，冲高一次不能算证明。'),
   ('两组点列各自作证','黑板上是平方分母，不是一次分母。先让正弦取一，你能找到越来越高的函数值；再让正弦取零，检查它是否总能返回。前一组证明无界，后一组否定无穷大。少一组，你得到的结论就不完整。现在解释给遐蝶听：为什么必须同时保留这两组？'),
   ('保留条件再迁移','回到原来的数列：奇数项等于下标，偶数项等于零。先分别观察两组，再决定无界和无穷大能不能互推。接着检查倒数定理里的非零条件。一个量不是恒零，并不代表它附近没有零点；你若忽略这一点，连倒数的定义域都还没过关。'),
  ],
  sides={
   'hyacine':'我们把证明分成两小步，好吗？先找一组能超过任意高度的值，再找一组始终回到零的值。第一步说明没有统一上界，第二步说明不能让所有值都超过阈值。你不用一次讲完整段，先把每组点列负责的任务说清。',
   'castor':'请保留平方。第一组函数值是括号里的数平方；第二组是精确的零，不是一个还在变化的无穷小。',
   'phainon':'我看到那几个高点，就想说它一定会越走越高。结果偶数项同学又回到零了！这回我不只盯着冲在前面的几个，先找齐门槛后所有还会回来的点。你帮我看看，两组证据是不是都找到了？',
  },
  checks=[
   check('guided-small-constant',0,'风堇把 ε 继续缩小。固定常数 0.0001 为什么不是无穷小？',['因为它不是正数','取 ε=0.00001，常数的误差始终不能小于 ε','因为任何能取到零的量都不算无穷小'],1,'无穷小要求同一过程中极限为零。固定非零常数的极限就是它自己；常零函数则满足定义。'),
   check('guided-specified-process',0,'同一个函数 x，x→0 与 x→+∞ 时应怎样判断？',['函数名字相同，分类也必须相同','前者是无穷小，后者趋正无穷；过程不可省略','只看 x 字母就能判断'],1,'分类针对函数在指定趋近过程中的行为，而不是给表达式贴永久标签。'),
   check('guided-absolute-infinity',0,'a_n=(-1)ⁿn，哪份结论同时保留大小与符号信息？',['|a_n|→∞，但 a_n 既不趋 +∞ 也不趋 -∞','因为正负交替，数列绝对值有界','a_n→+∞，负号最终不重要'],0,'绝对值恒为 n；任意晚仍有正项与负项，无法稳定在任一符号方向。'),
   check('guided-peaks-only',1,'只找到 x_n→0⁺ 且 f(x_n)→+∞，能直接断言 |f(x)|→∞ 吗？',['能，一组取值已经代表全部输入','不能，还要检查其余趋近点是否也最终超过每个阈值','不能，因为函数不允许用点列研究'],1,'一组趋近点能证明附近无界，却不能代表范围内全部输入。另一组零点正好否定了无穷大的要求。'),
   check('guided-squared-denominator',1,'x_n=1/(2πn+π/2)，代入 sin(1/x)/x² 后应得到什么？',['2πn+π/2','(2πn+π/2)²','0'],1,'正弦取一，而 1/x_n² 是倒数的平方。不要沿用漏掉平方的旧解析。'),
   check('guided-zero-subsequence',1,'z_n=1/(nπ)→0⁺ 且 f(z_n)=0，为什么足以否定 |f|→∞？',['因为任意小范围内都有值不能超过 M=1','因为只要函数曾在一个孤立点为零就永远不能趋无穷','因为 0 是一个非常小但非零的变量'],0,'零点沿同一趋近过程无限接近目标。不是一个远处孤立零点，而是任意门槛都躲不开的反例。'),
   check('guided-eventual-nonzero',2,'α(x)=x sin(1/x)，x→0。它趋零且不恒为零，能直接在整个去心邻域取倒数吗？',['能，不恒零就意味着处处非零','不能，x=1/(nπ) 的零点不断靠近 0','不能，因为任何无穷小都没有倒数'],1,'倒数定理要求所研究的足够小范围内非零；零点累积时不能宣称倒数在整个去心邻域都有定义。'),
   check('guided-bounded-product',2,'x→0 时 x·sin(1/x) 为什么趋零？',['无穷小与任意量相乘都会趋零','|sin(1/x)|≤1，故乘积绝对值不超过 |x|','把 sin(1/x) 的极限直接当作 0'],1,'有界因子提供统一常数上界。正弦本身可以不收敛，但被趋零的幅度控制。'),
   check('guided-growing-sum',2,'n 个 1/n 相加为何不能套“有限个无穷小之和趋零”？',['因为 1/n 不是无穷小','因为项数随 n 增加，并非固定有限项；和恒等于 1','因为加法不适用于极限'],1,'对每个 n 虽然只有有限项，但定理要求项数固定，不能把这种变化项数的和当成固定有限项。'),
  ],
  extra=[
   example('a_n=n（n为奇数），a_n=0（n为偶数）。判断无界与无穷大。','无界但非绝对值无穷大。',[('奇数子列','a_(2k-1)=2k-1→+∞，可超过任意阈值。'),('偶数子列','a_(2k)=0，每个门槛后仍有零项。'),('量词判别','不存在统一界，但也不能使尾部全部绝对值超过 1，故无界但非无穷大。')]),
   example('用阈值定义证明 x→0 时 1/x²→+∞。','任意 M>0，取 δ=1/√M。',[('写目标','要使 1/x²>M，只需 0<|x|<1/√M。'),('选择输入范围','给定 M>0，取 δ=1/√M>0。'),('验证所有邻近输入','若 0<|x|<δ，则 1/x²>M，且函数值恒正，故趋 +∞。')]),
   example('x→0 时，求 x sin(1/x) 的极限。','0。',[('找统一上界','对所有 x≠0，|sin(1/x)|≤1。'),('控制整个乘积','0≤|x sin(1/x)|≤|x|。'),('使用夹逼','|x|→0，故乘积趋零，不需要正弦本身存在极限。')]),
   example('x→+∞，已知 f(x) 与 x f(x) 的有限极限存在，且 lim 3x f(x)=lim[4f(x)+6]。求 lim x f(x)。','2。',[('用已知的有限极限重写','f(x)=[x f(x)]·(1/x)，前因子趋有限数、后因子趋零，故 f(x)→0。'),('再代回等式','设 L=lim x f(x)，由极限运算法则有 3L=4·0+6。'),('得到结论','解得 L=2。不能只凭“无穷大乘很小”猜测，须先使用有限极限存在的条件。')]),
   example('已知 x→0 时 f(x)/x²→6，把 f(x) 写成主项与误差项。','f(x)=6x²+x²α(x)，其中 α(x)→0。',[('定义误差而非丢掉误差','在去心邻域令 α(x)=f(x)/x²-6。'),('由已知确定误差极限','α(x)→0，故 f(x)/x²=6+α(x)。'),('等式两边乘回 x²','得到 f(x)=6x²+x²α(x)；除非另有条件，不能写成处处 f(x)=6x²。')]),
   example('x→0⁺，比较 2x/x、2x²/x、2x/x² 的极限。','依次为 2、0、+∞；分子分母同趋零不能决定商。',[('先在 x≠0 化简','三个商依次是 2、2x、2/x。'),('分别按过程取极限','常数趋 2，2x 趋 0，2/x 趋 +∞。'),('回看条件','这都是 0/0 型表现，但结果不同；0/0 不是可直接运算的数。')]),
   example('判断 x→+∞ 时 x sin x 是否为无穷大。','在任意右侧尾区间无界，但不是绝对值无穷大。',[('找上升的取值','令 x_n=2πn+π/2→+∞，则 x_n sin x_n=x_n→+∞。'),('找持续返回的取值','令 z_n=nπ→+∞，则 z_n sin z_n=0。'),('两组都沿正无穷过程','第一组说明任意远处都能找到任意大的值；第二组说明任意远处也有零值，故无界但不是无穷大。')]),
  ],
  formulas=['无界：∀M>0，∃n：|a_n|>M；无穷大：∀M>0，∃N，∀n>N：|a_n|>M','0<|x|<1/√M ⇒ 1/x²>M；δ=1/√M','|x sin(1/x)|≤|x|→0','f=(xf)/x；lim(xf)有限 ⇒ lim f=0；3L=6','f/x²=6+α，α→0 ⇒ f=6x²+x²α','x≠0 时先约分；x→0⁺：2→2，2x→0，2/x→+∞','x_n=2πn+π/2 ⇒ x_n sin x_n=x_n；z_n=nπ ⇒ z_n sin z_n=0'],
  legacy_explanation='原迁移题指奇数项为 n、偶数项为 0 的数列。a_(2k-1)=2k-1 无界，而 a_(2k)=0，任意门槛后仍有零项，故无界但非无穷大。',
  legacy_choices=['奇数子列任意大，偶数子列恒为零；不能控制全部尾项','只看到任意高的奇数项，便断言所有尾项最终都很大'])
